// flagNamesMixedDamage renders the set bits of value as 'A|B' — '0' for the
// empty set, bits past the declared variants as hex
String flagNamesMixedDamage(int value) {
  final names = <String>[];
  if (value & (1 << 0) != 0) {
    names.add('Bleeding');
  }
  if (value & (1 << 1) != 0) {
    names.add('Burning');
  }
  if (value & (1 << 2) != 0) {
    names.add('Stunned');
  }
  if (value & (1 << 3) != 0) {
    names.add('Slowed');
  }
  if (value & (1 << 4) != 0) {
    names.add('Poisoned');
  }
  if (value & (1 << 5) != 0) {
    names.add('Shielded');
  }
  if (value & (1 << 6) != 0) {
    names.add('Airborne');
  }
  if (value & (1 << 7) != 0) {
    names.add('Downed');
  }
  if (value >>> 8 != 0) {
    names.add('0x${Schema.hex64((value >>> 8) << 8)}');
  }
  return names.isEmpty ? '0' : names.join('|');
}

