    wordIndex++;
    scratchBits -= 64;
    scratch = v >>> (5 - scratchBits);
  }
  {
    final pad = scratchBits & 7;
    if (pad != 0) {
      scratchBits += 8 - pad;
      if (scratchBits >= 64) {
        view.setUint64(wordIndex * 8, scratch, Endian.little);
        wordIndex++;
        scratchBits -= 64;
        scratch = 0;
      }
    }
  }
  {
    var i0 = 0;
    for (; i0 + 4 <= value.payloadLength; i0 += 4) {
      v =
          value.payload[i0] |
          (value.payload[i0 + 1] << 8) |
          (value.payload[i0 + 2] << 16) |
          (value.payload[i0 + 3] << 24);
      scratch |= v << scratchBits;
      scratchBits += 32;
      if (scratchBits >= 64) {
        view.setUint64(wordIndex * 8, scratch, Endian.little);
        wordIndex++;
        scratchBits -= 64;
        scratch = v >>> (32 - scratchBits);
      }
    }
    for (; i0 < value.payloadLength; i0++) {
      v = value.payload[i0];
      scratch |= v << scratchBits;
      scratchBits += 8;
      if (scratchBits >= 64) {
        view.setUint64(wordIndex * 8, scratch, Endian.little);
        wordIndex++;
        scratchBits -= 64;
        scratch = v >>> (8 - scratchBits);
      }
    }
  }
  {
    final x = Schema.fround(value.aimX);
    assert(x.isFinite);
    var n = Schema.fround(Schema.fround(x + 1.0) / 2.0);
    if (!(n >= 0.0)) {
      n = 0.0;
    } else if (!(n <= 1.0)) {
      n = 1.0;
    }
    v = Schema.fround(Schema.fround(n * 200.0) + 0.5).floor();
    if (v > 200) v = 200;
  }
  scratch |= v << scratchBits;
  scratchBits += 8;
  if (scratchBits >= 64) {
    view.setUint64(wordIndex * 8, scratch, Endian.little);
    wordIndex++;
    scratchBits -= 64;
    scratch = v >>> (8 - scratchBits);
  }
  {
    final x = Schema.fround(value.aimY);
    assert(x.isFinite);
    var n = Schema.fround(Schema.fround(x + 1.0) / 2.0);
    if (!(n >= 0.0)) {
      n = 0.0;
    } else if (!(n <= 1.0)) {
      n = 1.0;
    }
    v = Schema.fround(Schema.fround(n * 200.0) + 0.5).floor();
