    scratch = v >>> (8 - scratchBits);
  }
  Schema.f32[0] = value.recoil;
  v = Schema.u32[0];
  assert((v & 0x7f800000) != 0x7f800000); // finite only (SPEC §4.3)
  scratch |= v << scratchBits;
  scratchBits += 32;
  if (scratchBits >= 64) {
    view.setUint64(wordIndex * 8, scratch, Endian.little);
    wordIndex++;
    scratchBits -= 64;
    scratch = v >>> (32 - scratchBits);
  }
  assert(value.drift.isFinite);
  v = Schema.float64BitsFromDouble(value.drift);
  scratch |= v << scratchBits;
  scratchBits += 64;
  if (scratchBits >= 64) {
    view.setUint64(wordIndex * 8, scratch, Endian.little);
    wordIndex++;
    scratchBits -= 64;
    scratch = v >>> (64 - scratchBits);
  }
  v = value.wideKey.lo;
  scratch |= v << scratchBits;
  scratchBits += 64;
  if (scratchBits >= 64) {
    view.setUint64(wordIndex * 8, scratch, Endian.little);
    wordIndex++;
    scratchBits -= 64;
    scratch = v >>> (64 - scratchBits);
  }
  v = value.wideKey.hi;
  scratch |= v << scratchBits;
  scratchBits += 64;
  if (scratchBits >= 64) {
    view.setUint64(wordIndex * 8, scratch, Endian.little);
    wordIndex++;
    scratchBits -= 64;
    scratch = v >>> (64 - scratchBits);
  }
  {
    const min = Int128(0xfffffff000000000, 0);
    const max = Int128(68719476736, 0);
    assert(value.flux >= min);
    assert(value.flux <= max);
    final off = (value.flux - min).toUnsigned();
    v = off.lo;
    scratch |= v << scratchBits;
    scratchBits += 64;
    if (scratchBits >= 64) {
      view.setUint64(wordIndex * 8, scratch, Endian.little);
      wordIndex++;
      scratchBits -= 64;
      scratch = v >>> (64 - scratchBits);
    }
    v = off.hi & 0x3fffffffff;
    scratch |= v << scratchBits;
    scratchBits += 38;
    if (scratchBits >= 64) {
      view.setUint64(wordIndex * 8, scratch, Endian.little);
      wordIndex++;
      scratchBits -= 64;
      scratch = v >>> (38 - scratchBits);
    }
  }
  assert(value.ping >= 0);
  assert(value.ping <= 64000);
  v = value.ping & 0xffff;
  scratch |= v << scratchBits;
  scratchBits += 20;
  if (scratchBits >= 64) {
    view.setUint64(wordIndex * 8, scratch, Endian.little);
    wordIndex++;
    scratchBits -= 64;
    scratch = v >>> (20 - scratchBits);
  }
  {
    final pad = scratchBits & 7;
    if (pad != 0) {
      scratchBits += 8 - pad;
      if (scratchBits >= 64) {
        view.setUint64(wordIndex * 8, scratch, Endian.little);
        wordIndex++;
        scratchBits -= 64;
        scratch = 0;
      }
    }
  }
  assert(value.extra >= 0);
  assert(value.extra <= 255);
  assert(value.idleTicks >= 0);
  assert(value.idleTicks <= 15);
