  scratchBits += 37;
  if (scratchBits >= 64) {
    view.setUint64(wordIndex * 8, scratch, Endian.little);
    wordIndex++;
    scratchBits -= 64;
    scratch = v >>> (37 - scratchBits);
  }
  if (scratchBits != 0) {
    view.setUint64(wordIndex * 8, scratch, Endian.little);
  }
  return wordIndex * 8 + ((scratchBits + 7) >>> 3);
}

